-- Fixture AgihTugas satu sekolah (dijana oleh tests/fixtures/make_agihtugas_sample.php daripada kod legacy/).
-- Akaun ujian: admin@lama.test / Lama-Admin-2026, pk@lama.test / Lama-PK-2026, ketua@lama.test / Lama-Ketua-2026, guru1@lama.test / Lama-Guru-2026, guru2@lama.test / Lama-Guru-2026
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE teachers (id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT "",specialty TEXT NOT NULL DEFAULT "",capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 100), external_id TEXT);
CREATE TABLE positions (id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,weight INTEGER NOT NULL CHECK(weight BETWEEN 1 AND 10));
CREATE TABLE assignments (id INTEGER PRIMARY KEY,teacher_id INTEGER NOT NULL REFERENCES teachers(id) ON DELETE RESTRICT,position_id INTEGER NOT NULL UNIQUE REFERENCES positions(id) ON DELETE RESTRICT);
CREATE TABLE history (id INTEGER PRIMARY KEY,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_keys (
 id INTEGER PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE,
 prefix TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ("read","write")),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TEXT, revoked_at TEXT
);
CREATE TABLE allocation_config (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE position_rules (position_id INTEGER PRIMARY KEY REFERENCES positions(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE allocation_plans (id TEXT PRIMARY KEY, snapshot TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, applied_at INTEGER);
CREATE TABLE accounts (
 id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE,
 password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ("admin","pk","head","teacher")),
 teacher_id INTEGER UNIQUE REFERENCES teachers(id) ON DELETE RESTRICT, active INTEGER NOT NULL DEFAULT 1,
 auth_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE login_attempts (bucket TEXT PRIMARY KEY, attempts INTEGER NOT NULL, window_start INTEGER NOT NULL);
CREATE TABLE setup_codes (id INTEGER PRIMARY KEY CHECK(id=1), code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE workflow_revisions (
 id INTEGER PRIMARY KEY AUTOINCREMENT, status TEXT NOT NULL, payload TEXT NOT NULL, source_hash TEXT NOT NULL,
 submitted_by INTEGER NOT NULL REFERENCES accounts(id), submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 approved_by INTEGER REFERENCES accounts(id), approved_at TEXT, finalized_by INTEGER REFERENCES accounts(id), finalized_at TEXT,
 returned_by INTEGER REFERENCES accounts(id), returned_at TEXT, return_reason TEXT
);
CREATE TABLE workflow_state (id INTEGER PRIMARY KEY CHECK(id=1), status TEXT NOT NULL DEFAULT "draft", revision_id INTEGER REFERENCES workflow_revisions(id), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE school_assets (id TEXT PRIMARY KEY,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,bytes BLOB NOT NULL);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX teachers_external_id ON teachers(external_id) WHERE external_id IS NOT NULL;
PRAGMA writable_schema=OFF;
COMMIT;
